.dh-motes i:nth-child(1) { left: 18%; bottom: 18% }
.dh-motes i:nth-child(2) { left: 44%; bottom: 12% }
.dh-motes i:nth-child(3) { left: 68%; bottom: 22% }
.dh-motes i:nth-child(4) { left: 82%; bottom: 9% }
.dh-motes i:nth-child(5) { left: 32%; bottom: 30% }

/* 幽夜回廊 · 动效（逐帧精灵动画 / 战斗节奏 / 浮尘 / 牺牲场景 / 进页动效）
   纪律（对齐 archive）：只做有限动效、无计时器、无 WebGL；`html[data-reader-motion="paused"]` 即全部停摆。 */

/* 主角：12 层部件共用一个 steps(10) 时间基 ⇒ 严格同步 */
@keyframes dh-walk { from { background-position: 0 0 } to { background-position: -1800px 0 } }

/* 敌方逐帧序列（整帧精灵表横向拼接，像素零改动） */
@keyframes dh-boss { from { background-position: 0 0 } to { background-position: -644px 0 } }
@keyframes dh-spider { from { background-position: 0 0 } to { background-position: -420px 0 } }

/* 回合推进：敌方在页眉内向主角方向压近（原地往返，不触发整页重排） */
@keyframes dh-advance { 0% { transform: translateX(0) } 100% { transform: translateX(-22px) } }

/* 斩击闪光（CSS 自绘；不用素材） */
@keyframes dh-slash {
  0%, 72% { opacity: 0; transform: rotate(-24deg) scaleX(.2) }
  80% { opacity: .95; transform: rotate(-24deg) scaleX(1) }
  90%, 100% { opacity: 0; transform: rotate(-24deg) scaleX(1.12) }
}

/* 弹道飞行（一次飞行 = 一条弧线；循环即"下一发"，无累积对象） */
@keyframes dh-flight {
  0% { transform: translate(0, 0); opacity: 0 }
  14% { opacity: 1 }
  62% { transform: translate(178px, -26px); opacity: 1 }
  72%, 100% { transform: translate(214px, -34px); opacity: 0 }
}

/* 浮尘上升 */
@keyframes dh-rise {
  0% { transform: translate(0, 0); opacity: 0 }
  42% { opacity: .9 }
  100% { transform: translate(6px, -48px); opacity: 0 }
}

/* 牺牲场景渐显 */
@keyframes dh-requiem-in { from { opacity: 0 } to { opacity: 1 } }

/* —— 挂载 —— */
.dh-rig .dh-p { animation: dh-walk .82s steps(10) infinite }
.dh-foe-boss .dh-f { animation: dh-boss .72s steps(7) infinite }
.dh-foe-boss { animation: dh-advance 3s ease-in-out infinite alternate }
.dh-foe-spider .dh-f { animation: dh-spider .94s steps(3) infinite }
.dh-foe-spider { animation: dh-advance 3.8s ease-in-out infinite alternate }
.dh-slash { animation: dh-slash 2.6s ease-out infinite }
.dh-bullet { animation: dh-flight 3.4s linear infinite }
.dh-motes i { animation: dh-rise 5.2s ease-in-out infinite }
.dh-page.dh-fallen .dh-requiem { animation: dh-requiem-in .6s ease-out both }

/* 浮尘错相位（动画延迟不计入声明预算） */
.dh-motes i:nth-child(2) { animation-delay: -1s }
.dh-motes i:nth-child(3) { animation-delay: -2.2s }
.dh-motes i:nth-child(4) { animation-delay: -3.1s }
.dh-motes i:nth-child(5) { animation-delay: -4.3s }
.dh-foe-spider { animation-delay: -.6s }
.dh-bullet { animation-delay: -1.4s }

/* 进页动效（archive 契约 R6：data-reader-entry pending → playing）：用过渡实现，不额外占帧序列预算 */
.dh-hero, .dh-paper, .dh-hud, .dh-stage { transition: opacity .5s ease-out }
.dh-hero, .dh-hud { transition-delay: .1s }
[data-reader-entry="pending"] .dh-hero,
[data-reader-entry="pending"] .dh-paper,
[data-reader-entry="pending"] .dh-hud,
[data-reader-entry="pending"] .dh-stage { opacity: 0; transition: none }

/* 动效闸门：专注模式 / 水墨屏 / 省电 ⇒ running→paused 时全部停摆并保留姿态 */
html[data-reader-motion="paused"] .dh-page,
html[data-reader-motion="paused"] .dh-page * { animation-play-state: paused }

/* 尊重系统"减少动态效果"：整页动效静默，静态帧与装饰保留（观感不塌） */
@media (prefers-reduced-motion: reduce) {
  .dh-page, .dh-page * { animation: none !important }
  .dh-hero, .dh-paper, .dh-hud, .dh-stage { transition: none !important; opacity: 1 !important }
}

javascript:
/* 幽夜回廊 · 行为脚本
   ①段落语义分类（首段 / 对白段 / 场景分隔段，对齐 archive 的 as-lead / as-dialogue / as-scene）
   ②蓝条（本章/本页序列剩余）随翻页递减 ③红条走后端整书进度（CSS 侧 --rp-percent）
   ④整书进度触顶 ⇒ 页眉切「牺牲场景」 ⑤只读语义、无网络、无宿主对象。 */
(function () {
  var rt = window.readerTemplate;
  if (!rt) return;

  var FALLEN_AT = 99.5;

  /**
   * 取**页面壳**（`.dh-page`）。
   *
   * ⚠️ 不能用 `readerTemplate.source` —— 运行时的 `source` 是**正文根**
   * （`data-reader-flow="body"` 的那个元素，见 template-runtime.js 的 `get source()`），
   * 拿它去找 `.dh-page` 会恒为 null（壳是它的**祖先**）⇒ 脚本静默空转。
   * 正确取法：作者根 `#reader-template-root` 下的外壳（换壳会整块替换，故每次都要现取）。
   */
  function shell(event) {
    if (event && event.page && event.page.querySelector) {
      var viaEvent = event.page.querySelector('.dh-page');
      if (viaEvent) return viaEvent;
    }
    var root = document.getElementById('reader-template-root');
    if (!root) return null;
    if (root.classList && root.classList.contains('dh-page')) return root;
    return root.querySelector('.dh-page');
  }

  /** 整书进度（优先取运行时下发的 --rp-percent，取不到再退回宿主字段）。 */
  function progressNow() {
    var raw = '';
    try {
      raw = getComputedStyle(document.documentElement).getPropertyValue('--rp-percent');
    } catch (error) {
      raw = '';
    }
    var value = parseFloat(raw);
    if (isNaN(value)) {
      var fields = rt.fields || {};
      value = typeof fields.progress === 'number' ? fields.progress : 0;
    }
    return value;
  }

  /** 同步蓝条与牺牲场景。幂等：可被任意钩子重复调用。 */
  function sync(event) {
    var root = shell(event);
    if (!root) return;
    var total = rt.pageCount > 0 ? rt.pageCount : 1;
    var read = Math.min(1, (rt.pageIndex + 1) / total);
    root.style.setProperty('--dh-stamina', String(Math.max(0, (1 - read) * 100)));
    // 红条 = 整本剩余（宿主 --rp-percent）⇒ 读到末页它本就该归零。
    // 两个判据取"或"：宿主进度可能滞后一帧，而"已到末页"是沙箱自己算得准的末态；
    // 二者语义同源（末页 ⇔ 剩余 0），故合成一个判据，避免"分明读完了却没进牺牲场景"。
    var atLastPage = rt.pageCount > 0 && rt.pageIndex >= rt.pageCount - 1;
    var fallen = progressNow() >= FALLEN_AT || atLastPage;
    var marked = root.className.indexOf('dh-fallen') >= 0;
    if (fallen !== marked) root.classList.toggle('dh-fallen', fallen);
  }

  /**
   * 段落语义分类（**"分段正文样式"的可见主体**，2026-10-17 补齐）。
   *
   * 为什么必须有：archive 导出的主题无一例外都在 `beforeLayout` 里按**正文文本**给段落打语义类
   * （首段 / 对白段 / 场景分隔段），CSS 再据此给首行加重、对白描边、场景居中留白。本主题此前
   * 只在 CSS 里声明了 `.dh-lead` 规则，**没有任何代码给它加类** ⇒ 规则恒空（死规则），
   * 与 archive 主题逐套比对时正是用户报的「段落元素缺失」。
   *
   * 分类阈值**与 archive 严格同口径**（`/^[*＊※·•—_\-\s]{3,}$/` 判场景分隔；`/^[“「『"]/` 判对白；
   * 本章首个非分隔段判首段）⇒ 同一段正文在本主题与 archive 主题里得到**同一分类**，
   * 保证"导入导出 + 换主题"后分段观感连续，而不是各家一套判据。
   *
   * 时机：正文由运行时注入后才发 `beforeLayout`（首屏）与 `beforePage`（**换壳**后重新注入正文），
   * 二者都要挂 —— 只挂前者会让续页壳里的段落丢类（首屏有、翻页后没了）。
   * 幂等：`classList.toggle` 与 `data-dh-seq` 的一次性写入都可重复调用。
   */
  function classifyParagraphs() {
    var source = rt.source;                       // 正文根（与 archive 的 readerTemplate.source 同义）
    if (!source || !source.querySelectorAll) return 0;
    var paragraphs = source.querySelectorAll('.reader-paragraph');
    var lead = true, seq = 0;
    for (var i = 0; i < paragraphs.length; i++) {
      var p = paragraphs[i];
      var text = (p.textContent || '').trim();
      var scene = /^[*＊※·•—_\-\s]{3,}$/.test(text);
      p.classList.toggle('dh-scene', scene);
      p.classList.toggle('dh-dialogue', /^[“「『"]/.test(text));
      var isLead = lead && !!text && !scene;
      p.classList.toggle('dh-lead', isLead);
      if (text && !scene) lead = false;
      // 段序号（场景分隔段不编号）：供 CSS 侧做"悬挂读数"类装饰，重复调用不重号
      if (!p.hasAttribute('data-dh-seq')) p.setAttribute('data-dh-seq', String(++seq));
    }
    return paragraphs.length;
  }

  rt.on('beforeLayout', classifyParagraphs);
  rt.on('beforePage', classifyParagraphs);
  rt.on('beforeLayout', sync);
  rt.on('afterLayout', sync);
  rt.on('pageChange', sync);
  rt.on('fieldsChange', sync);

  // 换壳（C1）会整块替换作者根壳：新壳上的动画必须重新起，这里借 motionChange 再同步一次。
  rt.on('motionChange', function () {
    sync();
  });

  rt.on('dispose', function () {
    var root = shell();
    if (!root) return;
    root.classList.remove('dh-fallen');
    root.style.removeProperty('--dh-stamina');
  });

  sync();
})();
